var OAuthStateSchema = exports_external.string().refine((val) => {
  const pipeParts = val.split("|");
  if (pipeParts.length >= 2) {
    const [userId, timestampStr] = pipeParts;
    if (!userId || !timestampStr)
      return false;
    const timestamp = Number.parseInt(timestampStr, 10);
    return !isNaN(timestamp);
  }
  const colonParts = val.split(":");
  if (colonParts.length >= 3) {
    const [prefix, userId, timestampStr] = colonParts;
    if (!prefix || !userId || !timestampStr)
      return false;
    const timestamp = Number.parseInt(timestampStr, 10);
    return !isNaN(timestamp);
  }
  return false;
}, {
  message: 'Invalid OAuth state format. Expected "userId|timestamp|random" or "prefix:userId:timestamp:random"'
});
